import{_ as n,c as i,o as r,j as t,a0 as o,a as s,t as l}from"./chunks/framework.2ZoCBPOS.js";const b=JSON.parse('{"title":"K3s Networking Overview","description":"Comprehensive overview of K3s default networking components and configuration options for the PiKube Kubernetes Service cluster.","frontmatter":{"title":"K3s Networking Overview","permalink":"/docs/5-networking/1-k3s-networking","description":"Comprehensive overview of K3s default networking components and configuration options for the PiKube Kubernetes Service cluster.","last_modified_at":"2025-07 -11"},"headers":[],"relativePath":"5-networking/todelete-1-k3s-networking.md","filePath":"5-networking/todelete-1-k3s-networking.md"}'),d={name:"5-networking/todelete-1-k3s-networking.md"},c={id:"frontmatter-title",tabindex:"-1"};function h(a,e,g,u,p,f){return r(),i("div",null,[t("h1",c,[s(l(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=o('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>K3s comes with a complete networking stack pre-configured and ready to use. This integrated approach simplifies cluster deployment while maintaining the flexibility to customize networking components as needed.</p><h2 id="default-networking-stack" tabindex="-1">Default Networking Stack <a class="header-anchor" href="#default-networking-stack" aria-label="Permalink to &quot;Default Networking Stack&quot;">​</a></h2><p>K3s includes four core networking components that provide complete cluster connectivity:</p><h3 id="container-networking-interface-cni" tabindex="-1">Container Networking Interface (CNI) <a class="header-anchor" href="#container-networking-interface-cni" aria-label="Permalink to &quot;Container Networking Interface (CNI)&quot;">​</a></h3><ul><li><strong><a href="https://github.com/flannel-io/flannel" target="_blank" rel="noreferrer">Flannel</a></strong>: Default CNI plugin enabling pod-to-pod communication across nodes using VXLAN overlay networking</li></ul><h3 id="dns-services" tabindex="-1">DNS Services <a class="header-anchor" href="#dns-services" aria-label="Permalink to &quot;DNS Services&quot;">​</a></h3><ul><li><strong><a href="https://coredns.io/" target="_blank" rel="noreferrer">CoreDNS</a></strong>: Cluster DNS server providing service discovery and name resolution for pods and services</li></ul><h3 id="ingress-controller" tabindex="-1">Ingress Controller <a class="header-anchor" href="#ingress-controller" aria-label="Permalink to &quot;Ingress Controller&quot;">​</a></h3><ul><li><strong><a href="https://traefik.io/" target="_blank" rel="noreferrer">Traefik</a></strong>: HTTP reverse proxy and load balancer managing external access to cluster services</li></ul><h3 id="load-balancing" tabindex="-1">Load Balancing <a class="header-anchor" href="#load-balancing" aria-label="Permalink to &quot;Load Balancing&quot;">​</a></h3><ul><li><strong><a href="https://github.com/k3s-io/klipper-lb" target="_blank" rel="noreferrer">Klipper Load Balancer</a></strong>: Internal load balancer distributing traffic to services of type LoadBalancer</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Additional Resources</strong></p><p>For deeper understanding of Kubernetes networking concepts, see <a href="./../13-further-reading/kubernetes-networking-fundamentals.html">Kubernetes Networking Fundamentals</a></p></div><h2 id="configuring-flannel-as-the-cni" tabindex="-1">Configuring Flannel as the CNI <a class="header-anchor" href="#configuring-flannel-as-the-cni" aria-label="Permalink to &quot;Configuring Flannel as the CNI&quot;">​</a></h2><p>By default, K3S utilizes Flannel as its CNI, with <strong><code>Virtual Extensible Local Area Network</code></strong> (VXLAN) as the default backend mechanism. Flannel operates within the K3S process as a backend routine.</p><p>To customize network settings, K3S allows the specification of server installation options for defining pod and service network <strong><code>Classless Inter-Domain Routing</code></strong> (CIDRs), as well as selecting the Flannel backend.</p><table tabindex="0"><thead><tr><th>k3s server option</th><th>default value</th><th>Description</th></tr></thead><tbody><tr><td><code>--cluster-cidr</code></td><td>&quot;10.42.0.0/16&quot;</td><td>CIDR for pod IP allocation</td></tr><tr><td><code>--service-cidr</code></td><td>&quot;10.43.0.0/16&quot;</td><td>CIDR for service IP allocation</td></tr><tr><td><code>--flannel-backend</code></td><td>&quot;vxlan&quot;</td><td>Backend type (none, vxlan, ipsec, host-gw, wireguard)</td></tr></tbody></table><p>Each node is allocated a subnet (10.42.X.0/24) from which pods receive their IP addresses.</p><p><strong>Network Interfaces Created by Flannel:</strong></p><ul><li><strong>flannel.1:</strong> Acts as a VXLAN Tunnel Endpoint (VTEP), facilitating overlay networking. To view the <strong><code>flannel.1</code></strong> interface details, head to a PiKube Kubernetes Service node and run the below command</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flannel.1</span></span></code></pre></div><ul><li><strong>cni0:</strong> A bridge interface providing a gateway for pod communication within the node subnet (10.42.X.1/24). To view the <strong><code>cni0</code></strong> interface details, head to a PiKube Kubernetes Service node and run the below command</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cni0</span></span></code></pre></div><p>Traffic between cni0 and flannel.1 is managed through IP routing enabled on each node.</p><div class="caution custom-block github-alert"><p class="custom-block-title">🔜 WORK IN PROGRESS</p><p>TODO pikube-vxlan-network-with-flannel.drawio</p></div><h2 id="coredns-configuration-in-k3s" tabindex="-1">CoreDNS Configuration in K3S <a class="header-anchor" href="#coredns-configuration-in-k3s" aria-label="Permalink to &quot;CoreDNS Configuration in K3S&quot;">​</a></h2><p>K3S provides options to configure CoreDNS during server installation. CoreDNS is a flexible, extensible DNS server that can serve as the Kubernetes cluster DNS. Here are the configuration options available:</p><table tabindex="0"><thead><tr><th>k3s server option</th><th>default value</th><th>Description</th></tr></thead><tbody><tr><td><code>--cluster-dns</code></td><td>&quot;10.43.0.10&quot;</td><td>Specifies the cluster IP for the CoreDNS service. It should fall within the service CIDR range</td></tr><tr><td><code>--cluster-domain</code></td><td>&quot;cluster.local&quot;</td><td>Defines the cluster domain</td></tr></tbody></table><h2 id="configuring-traefik-as-the-ingress-controller" tabindex="-1">Configuring Traefik as the Ingress Controller <a class="header-anchor" href="#configuring-traefik-as-the-ingress-controller" aria-label="Permalink to &quot;Configuring Traefik as the Ingress Controller&quot;">​</a></h2><p><a href="https://traefik.io/" target="_blank" rel="noreferrer"><strong><code>Traefik</code></strong></a> is an HTTP reverse proxy and load balancer designed to ease microservices deployment. It comes embedded with K3S installations and is deployed by default. However, for users seeking more control over Traefik&#39;s version and configuration, it&#39;s possible to disable the default installation and proceed with a manual setup.</p><p>To exclude the embedded Traefik during K3S installation, use the <strong><code>--disable traefik</code></strong> option. Additional configuration details and advanced options for Traefik are available in the <a href="./../5-networking/3-ingress-controller-traefik.html"><strong><code>Traefik Ingress Controller Documentation</code></strong></a>.</p><h2 id="integrating-klipper-lb-as-the-load-balancer" tabindex="-1">Integrating Klipper-LB as the Load Balancer <a class="header-anchor" href="#integrating-klipper-lb-as-the-load-balancer" aria-label="Permalink to &quot;Integrating Klipper-LB as the Load Balancer&quot;">​</a></h2><p>By default, K3S deploys the <a href="https://github.com/k3s-io/klipper-lb" target="_blank" rel="noreferrer"><strong><code>Klipper Load Balancer</code></strong></a> upon cluster initialization. In scenarios where other alternative load balancing solutions like <code>Metal LB</code> or <code>Cilium</code> is preferred, it&#39;s necessary to disable <code>Klipper-LB</code>.</p><p>Disabling the embedded load balancer can be achieved by configuring all servers in the cluster with the <strong><code>--disable servicelb option</code></strong>. For those opting to install <strong><code>Metal LB</code></strong>, guidance and installation instructions are provided in the <a href="./../5-networking/2-load-balancer-metal-lb.html"><strong><code>Metal LB Documentation</code></strong></a>.</p><p>How to configure Cilium CNI Load balancer capabitily can be found in <a href="./../5-networking/5-cilium-kubernetes-cni.html">&quot;Cilium Documentation&quot;</a>.</p>',35))])}const m=n(d,[["render",h]]);export{b as __pageData,m as default};
